class AutocompleteTrie {
    class Node {
        Map<Character, Node> children = new HashMap<>();
        List<String> top = new ArrayList<>();
    }
    private Node root = new Node();
    private static final int K = 3;
    public void insert(String word) {
        Node curr = root;
        for (char c : word.toCharArray()) {
            curr = curr.children.computeIfAbsent(c, x -> new Node());
            curr.top.add(word);
            Collections.sort(curr.top);
            if (curr.top.size() > K) curr.top.remove(curr.top.size() - 1);
        }
    }
    public List<String> suggest(String prefix) {
        Node curr = root;
        for (char c : prefix.toCharArray()) {
            curr = curr.children.get(c);
            if (curr == null) return new ArrayList<>();
        }
        return curr.top;
    }
}

class BitTrie {
    class Node { Node[] children = new Node[2]; }
    private Node root = new Node();
    public void insert(int num) {
        Node curr = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (curr.children[bit] == null) curr.children[bit] = new Node();
            curr = curr.children[bit];
        }
    }
    public int maxXor(int num) {
        Node curr = root;
        int result = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int desired = 1 - bit;
            if (curr.children[desired] != null) {
                result |= (1 << i);
                curr = curr.children[desired];
            } else {
                curr = curr.children[bit];
            }
        }
        return result;
    }
}

class StreamChecker {
    class Node { Node[] children = new Node[26]; boolean isEnd; }
    private Node root = new Node();
    private StringBuilder stream = new StringBuilder();
    public StreamChecker(String[] words) {
        for (String w : words) {
            Node curr = root;
            for (int i = w.length() - 1; i >= 0; i--) {
                int idx = w.charAt(i) - 'a';
                if (curr.children[idx] == null) curr.children[idx] = new Node();
                curr = curr.children[idx];
            }
            curr.isEnd = true;
        }
    }
    public boolean query(char letter) {
        stream.append(letter);
        Node curr = root;
        for (int i = stream.length() - 1; i >= 0; i--) {
            int idx = stream.charAt(i) - 'a';
            if (curr.children[idx] == null) return false;
            curr = curr.children[idx];
            if (curr.isEnd) return true;
        }
        return false;
    }
}

class TrieWithCounts {
    class Node {
        Node[] children = new Node[26];
        int wordCount, prefixCount;
    }
    private Node root = new Node();
    public void insert(String word) {
        Node curr = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (curr.children[idx] == null) curr.children[idx] = new Node();
            curr = curr.children[idx];
            curr.prefixCount++;
        }
        curr.wordCount++;
    }
    public int countWordsEqualTo(String word) {
        Node node = find(word);
        return node == null ? 0 : node.wordCount;
    }
    public int countWordsStartingWith(String prefix) {
        Node node = find(prefix);
        return node == null ? 0 : node.prefixCount;
    }
    public void erase(String word) {
        Node curr = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            Node next = curr.children[idx];
            if (next == null) return;
            next.prefixCount--;
            if (next.prefixCount == 0) { curr.children[idx] = null; return; }
            curr = next;
        }
        curr.wordCount--;
    }
    private Node find(String s) {
        Node curr = root;
        for (char c : s.toCharArray()) {
            int idx = c - 'a';
            if (curr.children[idx] == null) return null;
            curr = curr.children[idx];
        }
        return curr;
    }
}
